#pragma once
#include "working_face_basis.hpp"
#include "lossless_evidence.hpp"
#include <memory>
namespace phase5_working_face_trace_codec_v2 {
constexpr std::uint64_t maximum_payload_bytes=4ULL*1024*1024;
inline void validate(const std::shared_ptr<phase5_working_face_basis_v1::Trace>& trace){
 auto need=[](bool b,const char* s){if(!b)throw std::invalid_argument(s);};if(!trace)return;need(trace->basis.size()<=512&&trace->endpoints.size()<=16384&&trace->refinements.size()<=1536,"bounded numerical working-face trace counts before codec");int failures=0;
 for(std::size_t i=0;i<trace->basis.size();++i){const auto& b=trace->basis[i];need(b.iteration>=0&&b.iteration<512&&b.original_count>0&&b.original_count<=144&&b.rank>=0&&b.rank<=b.original_count&&std::isfinite(b.span_error)&&b.span_error>=0&&b.blocker_row>=0&&b.blocker_row<20000&&(b.blocker_side==1||b.blocker_side==-1)&&b.error.size()<=1048576,"bounded finite basis metadata before codec");need(b.old_encoded.size()<=static_cast<std::size_t>(b.original_count)&&b.kept_positions.size()<=static_cast<std::size_t>(b.rank),"bounded basis array availability before codec");for(std::size_t j=0;j<b.old_encoded.size();++j){need(b.old_encoded[j]<40000&&b.old_encoded[j]/2!=static_cast<std::uint64_t>(b.blocker_row),"bounded oldface encoding before codec");for(std::size_t k=0;k<j;++k)need(b.old_encoded[k]/2!=b.old_encoded[j]/2,"unique oldface rows before codec");}for(std::size_t j=0;j<b.kept_positions.size();++j)need(b.kept_positions[j]>=0&&b.kept_positions[j]<b.original_count&&(j==0||b.kept_positions[j]>b.kept_positions[j-1]),"strictly ordered selected basis positions before codec");
  if(b.complete)need(b.error.empty()&&b.rank_measured&&b.span_measured&&b.rank>0&&b.rank<b.original_count&&b.span_error<=1e-12&&b.old_encoded.size()==static_cast<std::size_t>(b.original_count)&&b.kept_positions.size()==static_cast<std::size_t>(b.rank),"complete numerical basis availability before codec");else{++failures;need(i+1==trace->basis.size()&&!b.error.empty(),"only final failed numerical basis event retained");}
 }
 need(failures<=1,"single failed basis event terminal byte bound");
 for(std::size_t i=0;i<trace->refinements.size();++i){const auto& e=trace->refinements[i];need(e.iteration>=0&&e.iteration<512&&e.step>=0&&e.step<3&&e.rank>0&&e.rank<=e.dimension&&e.dimension<=288&&e.reason>=0&&e.reason<=7,"bounded stop refinement coordinates before codec");need(std::isfinite(e.solution_inf)&&e.solution_inf>=0&&std::isfinite(e.correction_cap)&&e.correction_cap==std::max(1.,e.solution_inf)&&std::isfinite(e.initial_double_residual)&&e.initial_double_residual>=0&&e.initial_double_residual<=1e-10,"original initial LU gate and correction cap before codec");for(const auto& p:{std::pair<bool,double>{e.before_available,e.before},{e.correction_available,e.correction_inf},{e.after_available,e.after}})need(p.first?(std::isfinite(p.second)&&p.second>=0):p.second==0,"explicit finite refinement availability before codec");need(e.accepted==(e.reason==0),"refinement accepted reason binding");
  if(e.reason==2)need(!e.before_available&&!e.correction_available&&!e.after_available,"unavailable before residual");else need(e.before_available,"before residual available for later stages");
  if(e.reason==1)need(e.before==0&&!e.correction_available&&!e.after_available,"zero residual no correction");
  if(e.reason==3)need(!e.correction_available&&!e.after_available,"failed correction availability");
  if(e.reason==4)need(e.correction_available&&e.correction_inf>e.correction_cap&&!e.after_available,"large correction refused not clipped");
  if(e.reason>=5)need(e.correction_available&&e.correction_inf<=e.correction_cap,"candidate correction bound");
  if(e.reason==5||e.reason==6)need(!e.after_available,"unavailable candidate residual");
  if(e.reason==7)need(e.after_available&&e.after>=e.before,"no strict improvement retained");
  if(e.accepted)need(e.before_available&&e.before>0&&e.correction_available&&e.correction_inf<=e.correction_cap&&e.after_available&&e.after<e.before,"strictly improved bounded refinement before codec");
  if(i&&e.iteration==trace->refinements[i-1].iteration){const auto& b=trace->refinements[i-1];need(b.accepted&&e.step==b.step+1&&e.rank==b.rank&&e.dimension==b.dimension&&e.initial_double_residual==b.initial_double_residual&&e.before_available&&e.before==b.after,"ordered same-KKT refinement steps and exact residual continuity");}else need(e.step==0&&(!i||e.iteration>trace->refinements[i-1].iteration),"ordered outer iteration reset before codec");
 }
 for(const auto& e:trace->endpoints)need(e.iteration>=0&&e.iteration<512&&e.row>=0&&e.row<20000&&std::isfinite(e.start)&&std::isfinite(e.travel)&&std::isfinite(e.endpoint)&&std::isfinite(e.lower)&&std::isfinite(e.upper)&&std::isfinite(e.violation)&&e.violation>=0&&e.violation<=1e-12&&e.violation==std::max({0.,e.lower-e.endpoint,e.endpoint-e.upper})&&phase5_working_face_basis_v1::endpointWithinExistingNumericDomain(e.endpoint,e.lower,e.upper),"finite same-domain endpoint diagnostics before codec");
}
inline void emit(phase5_active_evidence_v1::Evidence& out,const std::shared_ptr<phase5_working_face_basis_v1::Trace>& trace,std::uint64_t cycle,std::uint64_t trial,const std::string& name){
 validate(trace);out.write(name,"NUMERICAL_WORKING_FACE_BASIS_FULL_ENDPOINT_AND_BOUNDED_KKT_REFINEMENT_TRACE_V2",[&](phase5_active_evidence_v1::BinaryFile& f){f.u64(cycle);f.u64(trial);f.u64(bool(trace));f.u64(trace?trace->basis.size():0);if(trace)for(const auto& b:trace->basis){for(auto x:{b.iteration,b.original_count,b.rank,b.blocker_row,b.blocker_side})f.u64(static_cast<std::uint64_t>(static_cast<std::int64_t>(x)));f.u64(b.rank_measured);f.u64(b.span_measured);f.u64(b.complete);f.number(b.span_error);f.text(b.error);f.u64(b.old_encoded.size());for(auto x:b.old_encoded)f.u64(x);f.u64(b.kept_positions.size());for(auto x:b.kept_positions)f.u64(x);}f.u64(trace?trace->refinements.size():0);if(trace)for(const auto& e:trace->refinements){for(int x:{e.iteration,e.step,e.rank,e.dimension,e.reason})f.u64(x);for(bool x:{e.before_available,e.correction_available,e.after_available,e.accepted})f.u64(x);for(double x:{e.before,e.after,e.correction_inf,e.solution_inf,e.correction_cap,e.initial_double_residual})f.number(x);}f.u64(trace?trace->endpoints.size():0);if(trace)for(const auto& e:trace->endpoints){f.u64(e.iteration);f.u64(e.row);for(double x:{e.start,e.travel,e.endpoint,e.lower,e.upper,e.violation})f.number(x);}f.text("Numerical optimizer hint only. V2 adds complete bounded stop-only KKT refinement records (iteration,step,rank,dimension,reason;before/correction/after availability,accepted;before/after extended residual norms rounded to double,correction_inf,solution_inf,cap=max(1,solution_inf),original initial double residual). Reasons0=accepted,1=zero,2=before unavailable,3=correction nonfinite,4=correction above cap,5=candidate nonfinite,6=after unavailable,7=no strict improvement. Only accepted steps change the solve value; all original initial LU/LLT/rank gates run first, final double residual1e-10/direction1e-12/outer512/10s/allrow gates unchanged. At most3 refinements per iteration/1536 events; unavailable values0 are placeholders. No vector clipping, rank threshold change or ordinary-drop-mask change.  Oldface encoded row*2+(side==+1?1:0), selected positions refer to original ordered working set; omitted positions become inactive and all original A/l/u rows remain. Measured flags distinguish unavailable rank/span data. Nonblocking only previously removed rows with actual finite full endpoint inside unchanged1e-12 numerical domain; every fractional step/full final rows rechecked. Span residual is not exactrank/removedQPconstraint proof. Original nativeSOLVED/full14756SI/literal200/400/B/privateC and physical-stop gates remain required. No actualstate or nativecandidate projection.");});
}
// Maximum:512*(144+143 IDs plus metadata/counts)<1.3MiB, atmost one
// 1MiB failed basis error,16384*64B endpoints plus constant codec text/header.
// Plus1536*120B refinement records and fixed text. 4MiB covers the whole file; new cleanup bound includes this in32MiB reserve.
}
